fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both arrays have equal length, we can zip and compare element-wise
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x < y)
     .collect()
}